<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$stmt=$db->prepare("SELECT p.*,c.name AS category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1"); $stmt->bind_param('i',$id); $stmt->execute(); $product=$stmt->get_result()->fetch_assoc();
if(!$product){ http_response_code(404); $pageTitle='Produkti nuk u gjet'; require __DIR__.'/includes/header.php'; echo '<div class="container empty-state"><h1>Produkti nuk u gjet</h1><a class="button button-dark" href="products.php">Kthehu te produktet</a></div>'; require __DIR__.'/includes/footer.php'; exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $qty=max(1,min(10,(int)($_POST['quantity']??1))); $_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+$qty; flash('success','Produkti u shtua në shportë.'); redirect('cart.php'); }
$pageTitle=$product['name']; $activePage='products'; require __DIR__.'/includes/header.php';
?>
<div class="container product-detail"><div class="detail-image"><img src="<?= e(product_image($product['image'])) ?>" alt="<?= e($product['name']) ?>"></div><div class="detail-copy"><p class="eyebrow"><?= e($product['category_name']) ?> / Nexa choice</p><h1><?= e($product['name']) ?></h1><div class="detail-price"><span class="price"><?= money((float)$product['price']) ?></span><?php if($product['old_price']): ?><span class="old-price"><?= money((float)$product['old_price']) ?></span><?php endif; ?></div><p class="detail-description"><?= nl2br(e($product['description'])) ?></p><div class="features"><div class="feature">✓ Garanci 12 muaj</div><div class="feature">✓ Kthim 14 ditë</div><div class="feature">✓ Produkt origjinal</div><div class="feature">✓ <?= (int)$product['stock'] ?> në stok</div></div><?php if($product['stock']>0): ?><form method="post" class="add-form"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="quantity"><button type="button" data-qty="-1">−</button><input type="number" name="quantity" value="1" min="1" max="<?= min(10,(int)$product['stock']) ?>"><button type="button" data-qty="1">+</button></div><button class="button button-dark" type="submit">Shto në shportë →</button></form><?php else: ?><p class="error-list">Ky produkt nuk është në stok.</p><?php endif; ?></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
